{"explanation":"Put four identical right triangles, with legs a and b and hypotenuse c, inside a square of side a+b. In one arrangement, the uncovered region is a square of area c². Rearranging the same four triangles leaves two squares of areas a² and b²; because the outer square and triangles are unchanged, c² = a² + b².","manimCode":"const a = 1.5;
const b = 2.1;
const L = a + b;
const P = (x, y) => [x - L / 2, y - L / 2 + 0.25, 0];
const colors = [BLUE_C, TEAL, BLUE_D, BLUE];

const title = new Text({ text: 'The Pythagorean theorem', color: WHITE, fontSize: 34 });
title.moveTo([0, 3.25, 0]);
const subtitle = new Text({ text: 'Same outer square. Same four triangles.', color: GRAY, fontSize: 22 });
subtitle.moveTo([0, 2.76, 0]);
const frame = new Square({ sideLength: L, color: WHITE });
frame.moveTo([0, 0.25, 0]);
frame.setStrokeWidth(3);
frame.setFillOpacity(0);

const first = [
  [[0, 0], [a, 0], [0, b]],
  [[L, 0], [a, 0], [L, a]],
  [[L, L], [L, a], [b, L]],
  [[0, L], [b, L], [0, b]]
];
const second = [
  [[0, a], [a, a], [0, L]],
  [[a, L], [a, a], [0, L]],
  [[a, 0], [L, 0], [a, a]],
  [[L, a], [L, 0], [a, a]]
];
function makeTriangle(corners, i) {
  const tri = new Polygon({ vertices: corners.map(([x, y]) => P(x, y)), color: colors[i] });
  tri.setFill(colors[i], 0.84);
  tri.setStrokeWidth(2);
  return tri;
}
function makeArea(corners) {
  const region = new Polygon({ vertices: corners.map(([x, y]) => P(x, y)), color: GOLD });
  region.setFill(GOLD, 0.42);
  region.setStrokeWidth(2);
  return region;
}
function makeLabel(str, x, y) {
  const label = new Text({ text: str, color: YELLOW, fontSize: 32 });
  label.moveTo(P(x, y));
  return label;
}
const triangles = first.map((corners, i) => makeTriangle(corners, i));
let areas = [makeArea([[a, 0], [L, a], [b, L], [0, b]])];
let areaLabels = [makeLabel('c²', L / 2, L / 2)];

const widthLabel = new Text({ text: 'a + b', color: WHITE, fontSize: 23 });
widthLabel.moveTo([0, 2.29, 0]);
const aLabel = new Text({ text: 'a', color: WHITE, fontSize: 22 });
aLabel.moveTo(P(a / 2, -0.29));
const bLabel = new Text({ text: 'b', color: WHITE, fontSize: 22 });
bLabel.moveTo(P(a + b / 2, -0.29));
const equation = new Text({ text: 'c² = a² + b²', color: YELLOW, fontSize: 38 });
equation.moveTo([0, -2.55, 0]);
const hint = new Text({ text: 'Click any blue triangle to rearrange', color: GRAY, fontSize: 21 });
hint.moveTo([0, -3.28, 0]);

scene.add(title, subtitle, frame, widthLabel, aLabel, bLabel);
await scene.play(new AnimationGroup([new FadeIn(areas[0]), ...triangles.map(t => new FadeIn(t))]));
scene.add(areaLabels[0]);
await scene.wait(1.2);

let arrangement = 0;
let busy = false;
async function rearrange() {
  if (busy) return;
  busy = true;
  const next = 1 - arrangement;
  const layout = next === 1 ? second : first;
  const oldAreas = areas;
  const oldLabels = areaLabels;
  await scene.play(new AnimationGroup([
    ...triangles.map((tri, i) => new Transform(tri, makeTriangle(layout[i], i))),
    ...oldAreas.map(region => new FadeOut(region)),
    ...oldLabels.map(label => new FadeOut(label))
  ]));
  oldAreas.forEach(region => scene.remove(region));
  oldLabels.forEach(label => scene.remove(label));
  if (next === 1) {
    areas = [
      makeArea([[0, 0], [a, 0], [a, a], [0, a]]),
      makeArea([[a, a], [L, a], [L, L], [a, L]])
    ];
    areaLabels = [makeLabel('a²', a / 2, a / 2), makeLabel('b²', a + b / 2, a + b / 2)];
  } else {
    areas = [makeArea([[a, 0], [L, a], [b, L], [0, b]])];
    areaLabels = [makeLabel('c²', L / 2, L / 2)];
  }
  scene.add(...areas);
  await scene.play(new AnimationGroup([...areas.map(region => new FadeIn(region)), ...areaLabels.map(label => new FadeIn(label))]));
  scene.add(...areaLabels);
  arrangement = next;
  busy = false;
}

await rearrange();
scene.add(equation, hint);
triangles.forEach(tri => makeClickable(tri, scene, { onClick: rearrange }));
await scene.wait(999999);"}

